def completar_correo(apps, schema_editor):
    """El correo de contacto de los casos que ya existían: el de su cuenta."""
    Caso = apps.get_model("devoluciones", "CasoDevolucion")
    for caso in Caso.objects.select_related("usuario"):
        caso.correo = caso.usuario.email if caso.usuario_id else ""
        if caso.motivo == "disconformidad":
            caso.motivo = "arrepentimiento"  # plan 00, C1
        caso.save(update_fields=["correo", "motivo"])



